/// <summary>
/// ADO#89454, CB518, Financial dimension deviations, LalitJ, 20-Nov-2023
/// </summary>
[ExtensionOf(tableStr(LedgerJournalName))]
final class METLedgerJournalName_Table_Extension
{   
}

Method.Source:
    /// <summary>
    /// Validates the field being modified
    /// </summary>
    /// <param name = "p1">
    /// The field which is modified by user
    /// </param>
    /// <returns>
    /// True if validation passes, else false
    /// </returns>
    public boolean validateField(FieldId p1)
    {
        boolean     isValid = next validateField(p1);

        if(isValid)
        {
            switch (p1)
            {
                case fieldNum(LedgerJournalName, METCopyDimensions):

                if(this.JournalType != LedgerJournalType::VendInvoiceRegister)
                {
                    isValid = checkFailed("@MET:CopyDimValidation");
                }
                break;
            }
        }        

        return isValid;
    }
